package za.co.crownedconnections;

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.constraints.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

@RestController
public class ApiController {
    private final JdbcTemplate db; private final PasswordEncoder passwords;
    @Value("${app.jwt-secret}") private String jwtSecret;
    public ApiController(JdbcTemplate db, PasswordEncoder passwords) { this.db=db; this.passwords=passwords; }
    private Map<String,Object> row(String sql,Object... args) { List<Map<String,Object>> r=db.queryForList(sql,args); return r.isEmpty()?null:r.get(0); }
    private List<Map<String,Object>> rows(String sql,Object... args) { return db.queryForList(sql,args); }
    private Map<String,Object> ok(String key,Object value) { return Map.of(key,value); }
    private RuntimeException bad(String message) { return new ResponseStatusException(HttpStatus.BAD_REQUEST,message); }
    private RuntimeException unauth(String message) { return new ResponseStatusException(HttpStatus.UNAUTHORIZED,message); }
    private RuntimeException forbidden(String message) { return new ResponseStatusException(HttpStatus.FORBIDDEN,message); }
    private RuntimeException conflict(String message) { return new ResponseStatusException(HttpStatus.CONFLICT,message); }
    private String token(Map<String,Object> user) { return Jwts.builder().subject(user.get("id").toString()).claim("email",user.get("email")).claim("role",user.get("role")).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofDays(1)))).signWith(Keys.hmacShaKeyFor(jwtSecret.getBytes(StandardCharsets.UTF_8))).compact(); }
    private Map<String,Object> user(HttpServletRequest request) {
        String h=request.getHeader("Authorization"); if(h==null||!h.startsWith("Bearer ")) throw unauth("Authentication required");
        try { var c=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(jwtSecret.getBytes(StandardCharsets.UTF_8))).build().parseSignedClaims(h.substring(7)).getPayload();
            Map<String,Object> u=row("SELECT id,email,role,first_name,last_name FROM users WHERE id=? AND deleted_at IS NULL",UUID.fromString(c.getSubject())); if(u==null) throw unauth("Account not found"); return u;
        } catch(ResponseStatusException e){throw e;} catch(Exception e){throw unauth("Invalid or expired token");}
    }
    private Map<String,Object> role(HttpServletRequest req,String role) { Map<String,Object> u=user(req); if(!role.equals(u.get("role").toString())) throw forbidden("Insufficient permissions"); return u; }

    @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","ok","service","crowned-connections-api","language","Java");}
    @GetMapping("/api/docs") public Map<String,Object> docs(){return Map.of("name","Crowned Connections API","version","1.0.0","stack","Java 17 / Spring Boot / PostgreSQL + PostGIS","endpoints",List.of("POST /api/auth/register","POST /api/auth/login","GET /api/auth/me","GET /api/salons","GET /api/salons/{id}","POST /api/salons","PUT /api/salons/{id}","GET /api/services","POST /api/services","GET /api/search","GET /api/availability","GET /api/appointments","POST /api/appointments","POST /api/appointments/{id}/decision"));}

    @PostMapping("/api/auth/register") public Map<String,Object> register(@RequestBody Map<String,Object> b){
        String email=str(b,"email").toLowerCase(Locale.ROOT), pass=str(b,"password"), first=str(b,"firstName"), last=str(b,"lastName"), role=Optional.ofNullable((String)b.get("role")).orElse("CUSTOMER");
        if(!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||pass.length()<8||first.isBlank()||last.isBlank()) throw bad("Provide a valid email, names and a password of at least 8 characters");
        if(!List.of("CUSTOMER","SALON_OWNER").contains(role)) throw bad("Invalid account role");
        try { Map<String,Object> u=row("INSERT INTO users(email,password_hash,role,first_name,last_name,phone) VALUES(?,?,?,?,?,?) RETURNING id,email,role,first_name,last_name",email,passwords.encode(pass),role,first,last,b.get("phone")); return Map.of("user",u,"token",token(u)); }
        catch(DataAccessException e){throw conflict("An account with that email already exists");}
    }
    @PostMapping("/api/auth/login") public Map<String,Object> login(@RequestBody Map<String,Object> b){String email=str(b,"email").toLowerCase(Locale.ROOT); Map<String,Object> u=row("SELECT id,email,role,first_name,last_name,password_hash FROM users WHERE lower(email)=? AND deleted_at IS NULL",email); if(u==null||!passwords.matches(str(b,"password"),u.get("password_hash").toString()))throw unauth("Email or password is incorrect");u.remove("password_hash");return Map.of("user",u,"token",token(u));}
    @GetMapping("/api/auth/me") public Map<String,Object> me(HttpServletRequest req){return ok("user",user(req));}
    @DeleteMapping("/api/auth/me") public Map<String,Object> deleteAccount(HttpServletRequest req){Map<String,Object> u=user(req);db.update("UPDATE users SET deleted_at=now(),updated_at=now() WHERE id=?",u.get("id"));return Map.of("message","Account deleted");}
    private String str(Map<String,Object>b,String k){Object v=b.get(k);if(v==null)throw bad("Missing field: "+k);return v.toString().trim();}
    private int integer(Map<String,Object>b,String k,int min,int max){try{int n=((Number)b.get(k)).intValue();if(n<min||n>max)throw bad("Invalid value for "+k);return n;}catch(ClassCastException|NullPointerException e){throw bad("Missing or invalid field: "+k);}}

    @GetMapping("/api/salons") public Map<String,Object> salons(){return ok("salons",rows("SELECT s.id,s.name,s.description,s.city,s.province,s.suburb,s.business_type,s.rating_avg,s.rating_count,ST_Y(l.point::geometry) latitude,ST_X(l.point::geometry) longitude FROM salon_profiles s JOIN locations l ON l.id=s.location_id WHERE s.deleted_at IS NULL ORDER BY s.name"));}
    @GetMapping("/api/salons/{id}") public Map<String,Object> salon(@PathVariable UUID id){Map<String,Object>s=row("SELECT s.*,ST_Y(l.point::geometry) latitude,ST_X(l.point::geometry) longitude FROM salon_profiles s JOIN locations l ON l.id=s.location_id WHERE s.id=? AND s.deleted_at IS NULL",id);if(s==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Salon not found");return Map.of("salon",s,"services",rows("SELECT sv.id,sv.name,sv.description,sv.duration_minutes,ss.price_cents FROM salon_services ss JOIN services sv ON sv.id=ss.service_id WHERE ss.salon_id=? AND ss.deleted_at IS NULL AND sv.deleted_at IS NULL ORDER BY sv.name",id),"staff",rows("SELECT id,display_name FROM salon_staff WHERE salon_id=? AND active=true ORDER BY display_name",id));}
    @PostMapping("/api/salons") public Map<String,Object> createSalon(HttpServletRequest req,@RequestBody Map<String,Object>b){Map<String,Object>u=role(req,"SALON_OWNER");
        String name=str(b,"name"),phone=str(b,"phone"),address=str(b,"addressLine"),suburb=str(b,"suburb"),city=str(b,"city"),province=str(b,"province"),postal=str(b,"postalCode"),type=Optional.ofNullable((String)b.get("businessType")).orElse("SALON");double lat=num(b,"latitude"),lng=num(b,"longitude");
        if(lat < -90||lat>90||lng < -180||lng>180)throw bad("Invalid coordinates");
        UUID loc=UUID.fromString(row("INSERT INTO locations(point) VALUES(ST_SetSRID(ST_MakePoint(?,?),4326)::geography) RETURNING id",lng,lat).get("id").toString());
        Map<String,Object>s=row("INSERT INTO salon_profiles(owner_user_id,location_id,name,description,phone,address_line,suburb,city,province,postal_code,business_type) VALUES(?,?,?,?,?,?,?,?,?,?,?) RETURNING *",u.get("id"),loc,name,b.get("description"),phone,address,suburb,city,province,postal,type);
        db.update("INSERT INTO salon_staff(salon_id,display_name) VALUES(?,'Lead Stylist')",s.get("id"));return ok("salon",s);}
    private double num(Map<String,Object>b,String k){try{return ((Number)b.get(k)).doubleValue();}catch(Exception e){throw bad("Missing or invalid field: "+k);}}
    @PutMapping("/api/salons/{id}") public Map<String,Object> updateSalon(HttpServletRequest req,@PathVariable UUID id,@RequestBody Map<String,Object>b){Map<String,Object>u=role(req,"SALON_OWNER");Map<String,Object>s=row("SELECT id,location_id FROM salon_profiles WHERE id=? AND owner_user_id=? AND deleted_at IS NULL",id,u.get("id"));if(s==null)throw forbidden("Salon not found or not owned by you");
        db.update("UPDATE salon_profiles SET name=COALESCE(?,name),description=COALESCE(?,description),phone=COALESCE(?,phone),address_line=COALESCE(?,address_line),suburb=COALESCE(?,suburb),city=COALESCE(?,city),province=COALESCE(?,province),postal_code=COALESCE(?,postal_code),updated_at=now() WHERE id=?",b.get("name"),b.get("description"),b.get("phone"),b.get("addressLine"),b.get("suburb"),b.get("city"),b.get("province"),b.get("postalCode"),id);return ok("salon",row("SELECT * FROM salon_profiles WHERE id=?",id));}

    @GetMapping("/api/services") public Map<String,Object> services(){return ok("services",rows("SELECT id,name,description,category,duration_minutes FROM services WHERE deleted_at IS NULL ORDER BY name"));}
    @PostMapping("/api/services") public Map<String,Object> createService(HttpServletRequest req,@RequestBody Map<String,Object>b){Map<String,Object>u=role(req,"SALON_OWNER");Map<String,Object>s=row("SELECT id FROM salon_profiles WHERE owner_user_id=? AND deleted_at IS NULL LIMIT 1",u.get("id"));if(s==null)throw bad("Create your salon first");String name=str(b,"name");int duration=integer(b,"durationMinutes",15,480),price=integer(b,"priceCents",0,Integer.MAX_VALUE);Map<String,Object>sv=row("INSERT INTO services(name,description,duration_minutes) VALUES(?,?,?) RETURNING id,name,description,duration_minutes",name,b.get("description"),duration);db.update("INSERT INTO salon_services(salon_id,service_id,price_cents) VALUES(?,?,?)",s.get("id"),sv.get("id"),price);sv.put("price_cents",price);return ok("service",sv);}

    @GetMapping("/api/search") public Map<String,Object> search(@RequestParam(required=false)String q,@RequestParam(required=false)Double lat,@RequestParam(required=false)Double lng,@RequestParam(defaultValue="10")double radiusKm,@RequestParam(required=false)Integer minPriceCents,@RequestParam(required=false)Integer maxPriceCents,@RequestParam(required=false)Double minRating){
        if((lat==null)!=(lng==null))throw bad("lat and lng must be supplied together");if(radiusKm<1||radiusKm>100)throw bad("radiusKm must be between 1 and 100");String term=q==null||q.isBlank()?null:"%"+q.trim().toLowerCase(Locale.ROOT)+"%";
        String distance=lat==null?"NULL::double precision":"ST_Distance(l.point,ST_SetSRID(ST_MakePoint(?,?),4326)::geography)/1000";
        String sql="SELECT DISTINCT ON(s.id) s.id,s.name,s.description,s.city,s.province,s.suburb,s.business_type,s.rating_avg,s.rating_count,ss.id salon_service_id,sv.id service_id,sv.name service_name,ss.price_cents,sv.duration_minutes,"+distance+" distance_km FROM salon_profiles s JOIN locations l ON l.id=s.location_id JOIN salon_services ss ON ss.salon_id=s.id AND ss.deleted_at IS NULL JOIN services sv ON sv.id=ss.service_id AND sv.deleted_at IS NULL WHERE s.deleted_at IS NULL AND (? IS NULL OR lower(s.name||' '||coalesce(s.description,'')||' '||sv.name) LIKE ?) AND (? IS NULL OR ss.price_cents>=?) AND (? IS NULL OR ss.price_cents<=?) AND (? IS NULL OR s.rating_avg>=?)"+(lat==null?"":" AND ST_DWithin(l.point,ST_SetSRID(ST_MakePoint(?,?),4326)::geography,?)")+" ORDER BY s.id,ss.price_cents ASC";
        List<Object> p=new ArrayList<>();if(lat!=null){p.add(lng);p.add(lat);}p.add(term);p.add(term);p.add(minPriceCents);p.add(minPriceCents);p.add(maxPriceCents);p.add(maxPriceCents);p.add(minRating);p.add(minRating);if(lat!=null){p.add(lng);p.add(lat);p.add(radiusKm*1000);}List<Map<String,Object>> result=db.queryForList(sql,p.toArray());return ok("results",result);}

    @GetMapping("/api/availability") public Map<String,Object> availability(@RequestParam UUID salonId,@RequestParam UUID serviceId,@RequestParam String date,@RequestParam(required=false)UUID stylistId){LocalDate d;try{d=LocalDate.parse(date);}catch(Exception e){throw bad("date must use yyyy-MM-dd");}if(d.isBefore(LocalDate.now(ZoneId.of("Africa/Johannesburg"))))throw bad("Date must not be in the past");Map<String,Object> service=row("SELECT duration_minutes FROM services WHERE id=? AND deleted_at IS NULL",serviceId);if(service==null)throw bad("Service not found");int duration=((Number)service.get("duration_minutes")).intValue();int weekday=d.getDayOfWeek().getValue();List<Map<String,Object>> staff=stylistId==null?rows("SELECT st.id,st.display_name, a.start_local,a.end_local FROM salon_staff st JOIN availability a ON a.stylist_id=st.id WHERE st.salon_id=? AND st.active=true AND a.weekday=? AND a.active=true",salonId,weekday):rows("SELECT st.id,st.display_name,a.start_local,a.end_local FROM salon_staff st JOIN availability a ON a.stylist_id=st.id WHERE st.salon_id=? AND st.id=? AND st.active=true AND a.weekday=? AND a.active=true",salonId,stylistId,weekday);
        if(row("SELECT 1 FROM blocked_dates WHERE salon_id=? AND blocked_date=?",salonId,d)!=null)return ok("slots",List.of());List<Map<String,Object>> slots=new ArrayList<>();ZoneId zone=ZoneId.of("Africa/Johannesburg");for(Map<String,Object> st:staff){LocalTime start=LocalTime.parse(st.get("start_local").toString()),end=LocalTime.parse(st.get("end_local").toString());for(LocalTime t=start;t.plusMinutes(duration).compareTo(end)<=0;t=t.plusMinutes(30)){ZonedDateTime z=ZonedDateTime.of(d,t,zone);if(z.toInstant().isBefore(Instant.now().plusSeconds(60)))continue;Timestamp a=Timestamp.from(z.toInstant()),b=Timestamp.from(z.plusMinutes(duration).toInstant());if(row("SELECT 1 FROM appointments WHERE stylist_id=? AND status IN ('PENDING','CONFIRMED','RESCHEDULED') AND start_time < ? AND end_time > ?",st.get("id"),b,a)==null){Map<String,Object>x=new LinkedHashMap<>();x.put("stylistId",st.get("id"));x.put("stylistName",st.get("display_name"));x.put("startTime",z.toOffsetDateTime().toString());x.put("endTime",z.plusMinutes(duration).toOffsetDateTime().toString());slots.add(x);}}}return ok("slots",slots);}

    @GetMapping("/api/appointments") public Map<String,Object> appointments(HttpServletRequest req){Map<String,Object>u=user(req);String sql="SELECT a.id,a.status,a.start_time,a.end_time,a.payment_status,a.amount_cents,s.id salon_id,s.name salon_name,sv.name service_name,st.display_name stylist_name FROM appointments a JOIN salon_profiles s ON s.id=a.salon_id JOIN services sv ON sv.id=a.service_id LEFT JOIN salon_staff st ON st.id=a.stylist_id WHERE "+("SALON_OWNER".equals(u.get("role"))?"s.owner_user_id=?":"a.customer_user_id=?")+" ORDER BY a.start_time DESC";return ok("appointments",rows(sql,u.get("id")));}
    @PostMapping("/api/appointments") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> book(HttpServletRequest req,@RequestBody Map<String,Object>b){Map<String,Object>u=role(req,"CUSTOMER");UUID salonId=uuid(b,"salonId"),serviceId=uuid(b,"serviceId");UUID requested=b.get("stylistId")==null?null:uuid(b,"stylistId");OffsetDateTime start;try{start=OffsetDateTime.parse(str(b,"startTime"));}catch(Exception e){throw bad("startTime must be ISO-8601 with timezone");}if(!start.toInstant().isAfter(Instant.now()))throw bad("Appointment must be in the future");Map<String,Object>sv=row("SELECT ss.price_cents,sv.duration_minutes FROM salon_services ss JOIN services sv ON sv.id=ss.service_id WHERE ss.salon_id=? AND ss.service_id=? AND ss.deleted_at IS NULL",salonId,serviceId);if(sv==null)throw bad("Service not offered by salon");int duration=((Number)sv.get("duration_minutes")).intValue();OffsetDateTime end=start.plusMinutes(duration);LocalDate localDate=start.atZoneSameInstant(ZoneId.of("Africa/Johannesburg")).toLocalDate();LocalTime localStart=start.atZoneSameInstant(ZoneId.of("Africa/Johannesburg")).toLocalTime(),localEnd=end.atZoneSameInstant(ZoneId.of("Africa/Johannesburg")).toLocalTime();if(row("SELECT 1 FROM blocked_dates WHERE salon_id=? AND blocked_date=?",salonId,localDate)!=null)throw conflict("The salon is unavailable on that date");
        Map<String,Object>st;if(requested!=null)st=row("SELECT id FROM salon_staff WHERE id=? AND salon_id=? AND active=true",requested,salonId);else st=row("SELECT st.id FROM salon_staff st JOIN availability a ON a.stylist_id=st.id WHERE st.salon_id=? AND st.active=true AND a.weekday=? AND a.active=true AND a.start_local<=? AND a.end_local>=? AND NOT EXISTS(SELECT 1 FROM appointments ap WHERE ap.stylist_id=st.id AND ap.status IN ('PENDING','CONFIRMED','RESCHEDULED') AND ap.start_time < ? AND ap.end_time > ?) ORDER BY st.id LIMIT 1",salonId,localDate.getDayOfWeek().getValue(),localStart,localEnd,Timestamp.from(end.toInstant()),Timestamp.from(start.toInstant()));if(st==null)throw conflict("No stylist available for that time");
        if(row("SELECT 1 FROM availability WHERE stylist_id=? AND weekday=? AND active=true AND start_local<=? AND end_local>=?",st.get("id"),localDate.getDayOfWeek().getValue(),localStart,localEnd)==null)throw conflict("The selected time is outside the stylist's working hours");try{Map<String,Object>a=row("INSERT INTO appointments(customer_user_id,salon_id,service_id,stylist_id,start_time,end_time,status,amount_cents,payment_status) VALUES(?,?,?,?,?,?,'PENDING',?,'UNPAID') RETURNING id,status,start_time,end_time,amount_cents,payment_status",u.get("id"),salonId,serviceId,st.get("id"),Timestamp.from(start.toInstant()),Timestamp.from(end.toInstant()),sv.get("price_cents"));return ok("appointment",a);}catch(DataAccessException e){throw conflict("That stylist is already booked for the selected time");}}
    private UUID uuid(Map<String,Object>b,String k){try{return UUID.fromString(str(b,k));}catch(Exception e){throw bad("Invalid UUID: "+k);}}
    @PostMapping("/api/appointments/{id}/decision") public Map<String,Object> decision(HttpServletRequest req,@PathVariable UUID id,@RequestBody Map<String,Object>b){Map<String,Object>u=role(req,"SALON_OWNER");String d=str(b,"decision");if(!List.of("CONFIRMED","DECLINED").contains(d))throw bad("decision must be CONFIRMED or DECLINED");Map<String,Object>a=row("UPDATE appointments a SET status=?,updated_at=now() FROM salon_profiles s WHERE a.id=? AND a.salon_id=s.id AND s.owner_user_id=? AND a.status='PENDING' RETURNING a.id,a.status,a.start_time,a.end_time",d,id,u.get("id"));if(a==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Pending appointment not found for your salon");return ok("appointment",a);}
}
